  const runtimeData = data.filter(f => !/^data\/(?!people\/)[^/]+\/\d{3}\.json$/u.test(f) && !/^data\/people\/(?:extractions|resolutions)\//u.test(f));
  for (const directory of ['data/people/curation', 'data/people/schema', 'data/people/chronology']) {
